const $=s=>document.querySelector(s);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
let audio,master,playing=false,notesTimer,beat=0,voices=[];
function tone(freq,time,length,volume=.1,type='sine'){const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,time);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(volume,time+.05);g.gain.exponentialRampToValueAtTime(.0001,time+length);o.connect(g);g.connect(master);o.start(time);o.stop(time+length+.1);voices.push(o);o.onended=()=>{voices=voices.filter(v=>v!==o)}}
function phrase(){if(!playing)return;const t=audio.currentTime+.05;const roots=[110,87.307,130.813,97.999];const root=roots[Math.floor(beat/4)%4];tone(root/2,t,2.5,.13);tone(root,t,3.5,.04,'triangle');tone(root*1.5,t+.12,3.2,.025);tone(root*2,t+.3,3,.018);if(beat%2===0)tone(root*4,t+.5,1.1,.02);beat++}
async function setAudio(on){try{if(on){if(!audio){audio=new (window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=.45;master.connect(audio.destination)}await audio.resume();playing=true;phrase();clearInterval(notesTimer);notesTimer=setInterval(phrase,1350)}else{playing=false;clearInterval(notesTimer);if(audio)await audio.suspend()}$('#sound').setAttribute('aria-pressed',String(playing));$('#sound-label').textContent=playing?'ЗВУК ВКЛ.':'ЗВУК ВЫКЛ.'}catch{toast('Браузер не включил звук. Попробуй кнопку ещё раз.')}}
$('#sound').addEventListener('click',()=>setAudio(!playing));
$('#ignite').addEventListener('click',async()=>{await setAudio(true);document.body.classList.add('ignited');if(audio&&playing){const t=audio.currentTime;[55,82.4,110,164.8].forEach((f,i)=>tone(f,t+i*.1,1,.09,'triangle'))}setTimeout(()=>$('#manifesto').scrollIntoView({behavior:reduced?'instant':'smooth'}),reduced?0:650)});
$('#enter-silent').addEventListener('click',()=>$('#manifesto').scrollIntoView({behavior:reduced?'instant':'smooth'}));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close-dialog').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>{document.body.style.overflow='';if(d.id==='garage-dialog')window.garageActive=false})});
function openDialog(d){d.showModal();document.body.style.overflow='hidden'}
const worlds={survivor:{subtitle:'WORLD 01 / THE WALKING DEAD · INSPIRED',title:'История помнит твой выбор.',description:'Дорога впереди неизвестна. Рядом — свой человек. В этой главе главный герой уже выбран. Осталось решить, как пройти следующий поворот.',choices:['Проверить дорогу вместе','Сначала найти машину'],responses:['Заур запомнит, что ты остался рядом. Кооператив продолжается.','Бордовая машина найдена. На пассажирском месте, как обычно, свой человек.']},coop:{subtitle:'WORLD 02 / IT TAKES TWO · INSPIRED',title:'В одиночку можно. Вдвоём интереснее.',description:'Даже самый большой мир становится ближе, когда есть с кем его исследовать. Один держит деталь, второй собирает. Потом меняетесь. Как в хорошей дружбе.',choices:['Пригласить второго игрока','Собрать машину'],responses:['Игрок 2 уже в команде. Ещё со времён МУИТ.','Верстак ждёт. В гараже ниже есть маленькая сборка специально для тебя.']},north:{subtitle:'WORLD 03 / VALHEIM · INSPIRED',title:'Мир, который ты построишь сам.',description:'Начать с костра. Собрать первый дом. Однажды оглянуться — и увидеть целый свой мир. Пусть в нём всегда будет тепло и найдётся место для друзей.',choices:['Разжечь костёр','Отправиться в путь'],responses:['Костёр горит. Можно выдохнуть. Не каждый вечер должен быть битвой с боссом.','Новая территория открыта. Лучшие приключения ещё впереди.']}};
document.querySelectorAll('[data-world]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.world,w=worlds[key];$('#world-image').src=`assets/${key}.png`;$('#world-image').alt=b.querySelector('img').alt;$('#world-subtitle').textContent=w.subtitle;$('#world-title').textContent=w.title;$('#world-description').textContent=w.description;const host=$('#world-interaction');host.replaceChildren();const response=document.createElement('p');response.setAttribute('aria-live','polite');w.choices.forEach((c,i)=>{const btn=document.createElement('button');btn.textContent=c;btn.addEventListener('click',()=>{response.textContent=w.responses[i];if(audio&&playing)tone(440,audio.currentTime,.5,.04)});host.append(btn)});host.append(response);openDialog($('#world-dialog'))}));
document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{$('#full-photo').src='assets/'+b.dataset.photo;openDialog($('#photo-dialog'))}));
$('#chaos').addEventListener('click',()=>{const on=document.body.classList.toggle('chaos');$('#chaos').setAttribute('aria-pressed',String(on));$('#chaos-message').textContent=on?'Режим суеты включён. Спокойный парень временно отошёл.':'Спокойствие восстановлено. До следующего хорошего повода.';if(on&&audio&&playing)[220,277.18,329.63,440].forEach((f,i)=>tone(f,audio.currentTime+i*.12,.5,.05))});
let buildStep=0;const buildLabels=['Добавить колёса','Установить кузов','Собрать кабину','Включить фары','Собрать ещё раз'];$('#build').addEventListener('click',()=>{buildStep=(buildStep+1)%5;$('#toy').className='toy'+(buildStep?' step-'+buildStep:'');$('#build-label').textContent=buildLabels[buildStep];$('#build-progress').textContent=`0${buildStep} / 04 ДЕТАЛИ${buildStep===4?' — ГОТОВО':''}`;if(audio&&playing)tone(200+buildStep*110,audio.currentTime,.3,.05,'triangle');if(buildStep===4)toast('Собрано. Экземпляр 1 из 1. Для Заура.')});
$('#open-letter').addEventListener('click',()=>openDialog($('#letter-dialog')));$('#letter-done').addEventListener('click',()=>{$('#letter-dialog').close();toast('Сохранение: Chapter 25. Продолжение следует.')});
let garageLoaded=false;async function openGarage(){openDialog($('#garage-dialog'));window.garageActive=true;if(!garageLoaded){try{const module=await import('./garage.js');await module.initGarage();garageLoaded=true;$('#three-status').textContent='Ferrari 458 Italia · модель: vicent091036'}catch(e){console.error(e);$('#three-status').textContent='Не удалось включить WebGL. Иллюстрация гаража доступна на главной странице.';const img=document.createElement('img');img.src='assets/garage.png';img.alt='Гараж Заура';Object.assign(img.style,{width:'100%',height:'100%',objectFit:'cover',opacity:'.5'});$('#three-host').replaceChildren(img)}}}
$('#open-garage').addEventListener('click',openGarage);$('#open-garage-2').addEventListener('click',openGarage);
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.garage-heading,.garage-layout,.world-heading,.world-grid,.memories-heading,.photo-strip,.build-layout').forEach(el=>{el.classList.add('reveal');observer.observe(el)});
document.addEventListener('visibilitychange',()=>{if(audio&&playing){if(document.hidden)audio.suspend();else audio.resume().catch(()=>{})}});
